package com.spendwise.transaction;
import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/transactions") public class TransactionController { private final TransactionService service; public TransactionController(TransactionService service){this.service=service;} @GetMapping public List<Transaction> list(@RequestParam(required=false) String month){return service.list(month);} @PostMapping public Transaction create(@Valid @RequestBody TransactionRequest r){return service.create(r);} @PutMapping("/{id}") public Transaction update(@PathVariable Long id,@Valid @RequestBody TransactionRequest r){return service.update(id,r);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.delete(id);} }
